function validate([n, rollMax]) {
  if (!Number.isInteger(n) || n < 1 || n > 5000) return 'n is between 1 and 5000.';
  if (!Array.isArray(rollMax) || rollMax.length !== 6) return 'rollMax has exactly 6 values.';
  if (rollMax.some(v => !Number.isInteger(v) || v < 1 || v > 15)) return 'Each rollMax value is between 1 and 15.';
  return null;
}

