function dieSimulator(n, rollMax) {
  const MOD = 1e9 + 7;
  let dp = Array.from({ length: 6 }, () => new Array(16).fill(0));
  for (let face = 0; face < 6; face++) {
    dp[face][1] = 1;
  }

  for (let roll = 2; roll <= n; roll++) {
    const endsWith = dp.map(row => row.reduce((sum, ways) => (sum + ways) % MOD, 0));
    const total = endsWith.reduce((sum, ways) => (sum + ways) % MOD, 0);
    const next = Array.from({ length: 6 }, () => new Array(16).fill(0));
    for (let face = 0; face < 6; face++) {
      next[face][1] = (total - endsWith[face] + MOD) % MOD;
      for (let run = 2; run <= rollMax[face]; run++) {
        next[face][run] = dp[face][run - 1];
      }
    }
    dp = next;
  }

  let answer = 0;
  for (const row of dp) {
    for (const ways of row) {
      answer = (answer + ways) % MOD;
    }
  }
  return answer;
}

