function dieSimulator(n, rollMax) {
  // Simulate the state machine (last face, current run length) one roll at a time,
  // trying every face from every state.
  const MOD = 1e9 + 7;
  let ways = new Array(6 * 16).fill(0);
  for (let f = 0; f < 6; f++) ways[f * 16 + 1] = 1;
  for (let step = 1; step < n; step++) {
    const next = new Array(6 * 16).fill(0);
    for (let last = 0; last < 6; last++) {
      for (let run = 1; run <= 15; run++) {
        const count = ways[last * 16 + run];
        if (count === 0) continue;
        for (let f = 0; f < 6; f++) {
          const len = f === last ? run + 1 : 1;
          if (len > rollMax[f]) continue;
          next[f * 16 + len] = (next[f * 16 + len] + count) % MOD;
        }
      }
    }
    ways = next;
  }
  let total = 0;
  for (const c of ways) total = (total + c) % MOD;
  return total;
}

