function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = rand() < 0.5 ? 5000 : int(3000, 5000);
    return [n, Array.from({ length: 6 }, () => int(1, 15))];
  }
  const n = int(1, 8);
  const cap = rand() < 0.6 ? 3 : 15;
  return [n, Array.from({ length: 6 }, () => int(1, cap))];
}
